{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-03",
  "sketch": {
    "components": ["Account settings page", "Email change endpoint", "Profile update endpoint", "Session cookie handling", "User profile store"],
    "dataStores": ["User profile records (email, phone, shipping address)", "Session store"],
    "externalServices": ["Email delivery for notifications"],
    "trustBoundaries": ["Browser to web application", "Authenticated user to own account data"],
    "dataClasses": ["pii", "credentials"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Account takeover: change email with only a session, no password re-entry",
      "scenario": "An attacker who gets a session (shared or unlocked computer, stolen cookie, XSS) opens account settings and changes the email address. Because the change takes effect immediately with no password re-entry, they then use password reset on the new address and own the account permanently, including the stored phone number and shipping address.",
      "component": "Email change endpoint",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "The change takes effect immediately without re-entering the password." }
      ],
      "cwe": ["CWE-620", "CWE-304"],
      "plainLanguage": "Anyone who gets into your logged-in browser can swap your email and lock you out of your own account.",
      "requirement": {
        "title": "Require password re-authentication before email change",
        "given": "a logged-in user on the account settings page",
        "when": "they submit a new email address",
        "then": "the server rejects the change unless the current password (or equivalent step-up factor) is verified in that request"
      }
    },
    {
      "stride": "Spoofing",
      "title": "New email address is applied without proving the user controls it",
      "scenario": "A user (or an attacker in their session) sets the email to an address they do not own, or to an attacker-controlled address. Since the change takes effect immediately, all future reset links, receipts and security notices go to the new address, handing account recovery to whoever owns it and letting an attacker claim another person's address.",
      "component": "Email change flow",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "lets a logged-in user change their email address, phone number and shipping address. The change takes effect immediately" }
      ],
      "cwe": ["CWE-640"],
      "plainLanguage": "The new email is trusted straight away, so account recovery can be pointed at an address nobody verified.",
      "requirement": {
        "title": "Verify new email before it becomes the account email",
        "given": "a user submits a new email address",
        "when": "the request is accepted",
        "then": "the old address stays active until the user clicks a single-use, time-limited confirmation link sent to the new address"
      }
    },
    {
      "stride": "Tampering",
      "title": "Cross-site request forgery changes profile and email silently",
      "scenario": "Because sessions live in a cookie for 30 days, almost every visitor is authenticated at all times. An attacker hosts a page that auto-submits a form to the settings endpoint; the browser attaches the cookie and the victim's email, phone and shipping address are rewritten without any password prompt or interaction.",
      "component": "Profile update endpoint",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "Sessions are kept in a cookie for 30 days." }
      ],
      "cwe": ["CWE-352"],
      "plainLanguage": "A malicious web page could change your email for you just because you are still logged in.",
      "requirement": {
        "title": "Protect settings changes against CSRF",
        "given": "a state-changing request to the account settings endpoints",
        "when": "it arrives without a valid anti-CSRF token and SameSite-protected session cookie",
        "then": "the server rejects the request with no change applied"
      }
    },
    {
      "stride": "Spoofing",
      "title": "30-day cookie session gives a stolen cookie a month of access",
      "scenario": "An attacker who captures the session cookie once (shared device, malware, XSS, backup of browser profile) can act as the user for up to 30 days. With no re-authentication for sensitive changes and no shorter idle timeout, that single theft is enough to change the email and take the account over at leisure.",
      "component": "Session cookie handling",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "Sessions are kept in a cookie for 30 days." }
      ],
      "cwe": ["CWE-613"],
      "plainLanguage": "A stolen login cookie keeps working for a whole month.",
      "requirement": {
        "title": "Bound session lifetime and idle timeout",
        "given": "an authenticated session cookie",
        "when": "it has been idle beyond a short inactivity window or has exceeded its absolute lifetime",
        "then": "the server treats it as invalid and forces a fresh login, and the cookie is Secure, HttpOnly and SameSite"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Settings endpoint may trust a user-supplied account identifier",
      "scenario": "The settings endpoint updates email, phone and shipping address for the current user. If the account id or email is taken from the request body or query string rather than the session, an attacker changes the parameter to another customer's id and rewrites that person's email, then resets their password. This reads and overwrites other users' PII.",
      "component": "Profile update endpoint",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "The account settings page lets a logged-in user change their email address, phone number and shipping address." }
      ],
      "cwe": ["CWE-639"],
      "plainLanguage": "If the page trusts an account number sent by the browser, someone could edit another customer's details.",
      "requirement": {
        "title": "Derive the target account from the session only",
        "given": "a request to update account settings",
        "when": "the request includes any account or user identifier",
        "then": "the server ignores it and applies the change only to the account bound to the authenticated session"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No notice to the previous email, so takeover goes unnoticed and disputed",
      "scenario": "The change is applied immediately and the design describes no notification. A victim whose email was switched gets no message at the old address, so they cannot react or revoke, and support has no record of who made the change or from which session. Fraudulent address changes before a shipment cannot be disputed.",
      "component": "Email change flow",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        { "quote": "The change takes effect immediately without re-entering the password." }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "Nobody tells you your email or address was changed, so a takeover can stay hidden.",
      "requirement": {
        "title": "Notify and record contact-detail changes",
        "given": "a change to email, phone or shipping address",
        "when": "the change is confirmed",
        "then": "a security notice with a revoke link is sent to the previous email, and the actor, time, source IP and old/new values are recorded"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Other sessions stay valid after contact details change",
      "scenario": "After an email change, the 30-day cookies issued earlier keep working. If the legitimate owner recovers the account, the attacker's month-long session (or vice versa) remains authenticated, so the attacker can simply change the email back and regain control.",
      "component": "Session cookie handling",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "Sessions are kept in a cookie for 30 days." }
      ],
      "cwe": ["CWE-613"],
      "plainLanguage": "Changing your email does not kick other logged-in devices out, so an intruder stays in.",
      "requirement": {
        "title": "Invalidate other sessions on sensitive profile change",
        "given": "a confirmed email change or account recovery",
        "when": "the change is applied",
        "then": "all sessions other than the one performing the change are revoked server-side and must log in again"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Shipping address and phone number exposed by weak field handling",
      "scenario": "The page returns and accepts phone number and shipping address, which are personal data. If the settings response is cached by shared browsers/proxies or the fields are reflected without encoding, an attacker on a shared machine or via a scripted page reads another person's home address and phone number.",
      "component": "Account settings page",
      "likelihood": 2,
      "impact": 3,
      "evidence": [
        { "quote": "change their email address, phone number and shipping address" }
      ],
      "cwe": ["CWE-525", "CWE-79"],
      "plainLanguage": "Personal details like a home address could leak through browser caching or unescaped output.",
      "requirement": {
        "title": "Protect personal fields in the settings page",
        "given": "a page or API response containing phone number or shipping address",
        "when": "it is returned to the browser",
        "then": "it is marked no-store, and all user-supplied values are output-encoded for their context"
      }
    }
  ]
}
